---@class EventConfig
local EventConfig = T(Global, "EventConfig")

local EventMap = {}
local ValueMap = {}

local function initEvent()
    local path = FileUtil:getSettingPath() .. "/report/report.csv"
    local file = io.open(path, "r")
    if not file then
        return
    end
    local settings = CsvUtil.loadCsvFile(path, 1, false, true)
    for _, item in pairs(settings) do
        local keyTable = {}
        local keyIndex = 1
        while item["key" .. keyIndex] and item["key" .. keyIndex] ~= "" do
            local key = item["key" .. keyIndex]
            keyTable[key] = ValueMap[key]
            keyIndex = keyIndex + 1
        end
        EventMap[item.event] = keyTable
    end
end

local function initValue()
    local path = FileUtil:getSettingPath() .. "/report/reportKeyFuncConvert.csv"
    local file = io.open(path, "r")
    if not file then
        return
    end
    local settings = CsvUtil.loadCsvFile(path, 1, false, true)
    for _, item in pairs(settings) do
        if ValueMap[item.key] ~= nil then
            assert(false, "key :" .. item.key .. " exist")
        end
        if item.type == "string" then
            ValueMap[item.key] = "string"
        end
        if item.type == "bool" then
            ValueMap[item.key] = "boolean"
        end
        if item.type == "int" or item.type == "double" then
            ValueMap[item.key] = "number"
        end
    end
end

