function EventConfig:checkEventKey(event, event_map)
    local keyTable = EventMap[tostring(event)]
    if not keyTable then
        if isLocalWin then
            assert(false, event)
        end
        return false
    end

    for key, value in pairs(event_map) do
        local keyType = keyTable[key]
        if keyType == nil then
            if isLocalWin then
                assert(false, event .. " " .. key)
            end
            LogUtil.logError(string.format("event key type do not define , event = %s , key = %s", event, key))
        end
        if keyType == "number" then
            event_map[key] = tonumber(value) or 0
        end
        if keyType == "string" then
            event_map[key] = tostring(value)
        end
    end
    return true
end

function EventConfig:getEventValueKey(event)
    return EventMap[tostring(event)]
end

function EventConfig:registerEvent(event, event_map)
    EventMap[event] = event_map
end

return EventConfig